const body = $input.first().json.body || $input.first().json;

const migrationName = body.migration_name || 'unknown';
const errorMessage = body.error_message || 'No error details provided';
const database = body.database || 'unknown';
const environment = body.environment || 'unknown';
const timestamp = body.timestamp || new Date().toISOString();

// Parse error type
let errorType = 'UNKNOWN';
let rollbackCommand = '';

if (errorMessage.includes('duplicate') || errorMessage.includes('already exists')) {
  errorType = 'DUPLICATE_OBJECT';
  rollbackCommand = `-- Rollback duplicate:\nDROP TABLE IF EXISTS <table>;\n-- Then re-run migration`;
} else if (errorMessage.includes('foreign key') || errorMessage.includes('constraint')) {
  errorType = 'CONSTRAINT_VIOLATION';
  rollbackCommand = `-- Rollback constraint issue:\n-- Disable FK checks, rollback, re-enable\nSET session_replication_role = 'replica';\n-- Run rollback migration\nSET session_replication_role = 'origin';`;
} else if (errorMessage.includes('timeout') || errorMessage.includes('lock')) {
  errorType = 'LOCK_TIMEOUT';
  rollbackCommand = `-- Rollback lock timeout:\nSELECT pg_cancel_backend(pid)\nFROM pg_stat_activity\nWHERE state = 'active' AND query LIKE '%migration%';\n-- Retry migration during low traffic`;
} else {
  rollbackCommand = `-- Generic rollback:\n-- Check migration tool for down() method\n-- Run: migrate rollback --step=1`;
}

return [{
  json: {
    migration_name: migrationName,
    error_message: errorMessage,
    error_type: errorType,
    database: database,
    environment: environment,
    rollback_command: rollbackCommand,
    severity: environment === 'production' ? 'CRITICAL' : 'WARNING',
    timestamp: timestamp
  }
}];

